using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TransPort.Api.Modules.Construccion.DTOs;using TransPort.Api.Modules.Construccion.Repositories;
namespace TransPort.Api.Controllers;
[ApiController,Route("api/construcciones"),Authorize(Roles="AdministradorGeneral,Gerente,Empleado,Operativo")]
public sealed class ConstruccionesController(IConstruccionRepository repo):ControllerBase
{[HttpGet]public Task<IReadOnlyList<ConstruccionListadoDto>>Listar(string?estado,int?sedeId,string?busqueda,CancellationToken ct)=>repo.ListarAsync(estado,sedeId,busqueda,A(),ct);[HttpGet("opciones")]public Task<ConstruccionOpcionesDto>Opciones(CancellationToken ct)=>repo.OpcionesAsync(A(),ct);[HttpGet("{id:long}")]public async Task<IActionResult>Obtener(long id,CancellationToken ct){var x=await repo.ObtenerAsync(id,A(),ct);return x is null?NotFound():Ok(x);}[HttpPost]public async Task<IActionResult>Crear(CrearConstruccionRequest x,CancellationToken ct)=>Ok(new ResultadoConstruccionDto(await repo.CrearAsync(x,A(),ct)));[HttpPost("{id:long}/actividades")]public async Task<IActionResult>Actividad(long id,CrearActividadConstruccionRequest x,CancellationToken ct)=>Ok(new ResultadoConstruccionDto(await repo.CrearActividadAsync(id,x,A(),ct)));[HttpPost("actividades/{id:long}/avances")]public async Task<IActionResult>Avance(long id,AvanceConstruccionRequest x,CancellationToken ct)=>Ok(new ResultadoConstruccionDto(await repo.AvanceAsync(id,x,A(),ct)));[HttpPost("{id:long}/recursos")]public async Task<IActionResult>Recurso(long id,RecursoConstruccionRequest x,CancellationToken ct)=>Ok(new ResultadoConstruccionDto(await repo.RecursoAsync(id,x,A(),ct)));[HttpPut("{id:long}/estado")]public async Task<IActionResult>Estado(long id,EstadoConstruccionRequest x,CancellationToken ct)=>await repo.EstadoAsync(id,x.Estado,A(),ct)?NoContent():NotFound();[HttpDelete("{id:long}"),Authorize(Roles="AdministradorGeneral")]public async Task<IActionResult>Eliminar(long id,CancellationToken ct)=>await repo.EliminarAsync(id,A().UsuarioId,ct)?NoContent():NotFound();private AlcanceConstruccion A()=>new(int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!),User.IsInRole("AdministradorGeneral"));}
